mapper.select:
select DATATYPE_CD
from RULECONDITION_POSTFIXOBJECT
where ruleid = #{ruleid}
  and POSTFIXOBJECTNO = #{postfixobjectno}
  and RULECONDITIONNO = #{ruleconditionno}

    AND DATATYPE_CD IN('0','1','2')

select RETURNITEM_POSTFIX_DESC
from RULECONDITIONRETURNITEM
where RULEID = #{value}

SELECT ITEM_NM
  FROM RULEITEM
 WHERE ITEMID = #{value}

SELECT ITEMID
FROM RULEITEM
where ITEM_NM = #{itemNm}
AND IFID = #{ifid}
AND ITEM_USE_YN = 'Y'

mapper.update:
UPDATE RULE
SET RULE_NM = #{ruleNm}
    ,RULEALIAS_NM = #{rulealiasNm}
    ,RULE_DESC = #{ruleDesc}
    ,RULERETURN_TYPE = #{rulereturnType}
    ,RULESORT_CD = #{rulesortCd}

    ,ALLRETURN_YN = #{allreturnYn}

    ,RULE_VERNO = #{ruleVerno}


    ,RULE_STATE = #{ruleState}


    ,IFID = #{ifid}


    ,UPDATE_USERID = #{updateUserid}
    ,UPDATE_DATETIME = TO_CHAR(CURRENT_DATE, 'YYYYMMDDHH24MISS')
where RULEID = #{ruleid}

mapper.select:
SELECT DATATYPE_CD
FROM RULEITEM
WHERE ITEM_NM = #{value}

mapper.update:
UPDATE RULE SET
 ACTIVATE_YN = #{activeYn}
,ACTIVATE_DATETIME = CURRENT_DATE
WHERE RULEID = #{ruleid}

UPDATE RULE SET
RULE_STATE = '2'
WHERE RULEID = #{ruleid}

mapper.select:
select count(*)
from locks
where lockkey=#{ruleid}
and lockcode='002'
and userid=#{userid}

mapper.update:
UPDATE RULE SET
RULE_STATE = #{ruleState}
,DEPLOY_DATETIME = CURRENT_DATE
,DEPLOY_USERID = #{userId}
,RULE_APPLY_YN = #{ruleApplyYn}
,DEPLOY_WAIT_STATE_APPY_YN = NULL
,RULE_VERNO = CEIL(RULE_VERNO)
WHERE RULEID = #{ruleid}

UPDATE RULE SET
RULE_VERNO = #{ruleVerno}
WHERE RULEID = #{ruleid}

mapper.select:
SELECT MAX(RULE_VERNO)
FROM RULE_HIST
where RULEID = #{value}

mapper.insert:
INSERT INTO RULE_PROGRESS_HISTORY (
RULEID
,RULE_VERNO
,RULE_STATE
,CURRENT_RULE_APPLY_YN
,DEPLOY_WAIT_STATE_APPLY_YN
,UPDATE_USERID
,UPDATE_DATETIME
,HISTORY_NO
) VALUES (
#{ruleid}
,#{ruleVerno}
,#{ruleState}
,(select RULE_APPLY_YN from rule where ruleid = #{ruleid})
,#{deployWaitStateApplyYn}
,#{updateUserid}
,TO_CHAR(CURRENT_DATE, 'YYYYMMDDHH24MISS')
,(select NVL(MAX(HISTORY_NO)+1,0) as  HISTORY_NO
from RULE_PROGRESS_HISTORY
where ruleid = #{ruleid})
)

mapper.update:
UPDATE RULE
SET RULE_STATE = '3'
,DEPLOY_WAIT_STATE_APPY_YN = #{ruleApplyYn}
where RULEID = #{ruleid}

mapper.select:
SELECT DISTINCT '조건식' AS USE_GUBUN , SUBSTR(A.OBJECT_DATA, 3, LENGTH(A.OBJECT_DATA) - 3) AS RULEID , B.RULE_NM ,(select code_nm from clover_code where code_type='604' and code = B.RULE_STATE) as RULE_STATE ,(select user_nm from clover_user where user_id = B.UPDATE_USERID) as UPDATE_USERID ,(SUBSTR(B.UPDATE_DATETIME,0,4)||'/'||SUBSTR(B.UPDATE_DATETIME,5,2)||'/'||SUBSTR(B.UPDATE_DATETIME,7,2)||' '||SUBSTR(B.UPDATE_DATETIME,9,2)||':'||SUBSTR(B.UPDATE_DATETIME,11,2)||':'||SUBSTR(B.UPDATE_DATETIME,13,2) )as UPDATE_DATETIME , B.RULE_APPLY_YN FROM RULECONDITION_POSTFIXOBJECT A INNER JOIN RULE B ON SUBSTR(A.OBJECT_DATA, 3, LENGTH(A.OBJECT_DATA) - 3) = B.RULEID WHERE A.DATATYPE_CD = 4 AND A.RULEID = #{value}
UNION ALL
SELECT DISTINCT '반환값' AS USE_GUBUN , SUBSTR(A.OBJECT_DATA, 3, LENGTH(A.OBJECT_DATA) - 3) AS RULEID , B.RULE_NM ,(select code_nm from clover_code where code_type='604' and code = B.RULE_STATE) as RULE_STATE ,(select user_nm from clover_user where user_id = B.UPDATE_USERID) as UPDATE_USERID ,(SUBSTR(B.UPDATE_DATETIME,0,4)||'/'||SUBSTR(B.UPDATE_DATETIME,5,2)||'/'||SUBSTR(B.UPDATE_DATETIME,7,2)||' '||SUBSTR(B.UPDATE_DATETIME,9,2)||':'||SUBSTR(B.UPDATE_DATETIME,11,2)||':'||SUBSTR(B.UPDATE_DATETIME,13,2) )as UPDATE_DATETIME , B.RULE_APPLY_YN FROM RULECONDITIONRETURN_POSTOBJECT A INNER JOIN RULE B ON SUBSTR(A.OBJECT_DATA, 3, LENGTH(A.OBJECT_DATA) - 3) = B.RULEID WHERE A.DATATYPE_CD = 4 AND A.RULEID = #{value}

SELECT DISTINCT '반환항목' AS USE_GUBUN, A.RETURN_ITEMID AS ITEMID, B.ITEM_NM
FROM RULERETURNITEM_HIST A INNER JOIN RULEITEM B ON A.RETURN_ITEMID = B.ITEMID
WHERE RULEID = #{ruleid}
AND RULE_VERNO = #{ruleVerno}
UNION ALL
SELECT DISTINCT '조건식' AS USE_GUBUN, SUBSTR(A.OBJECT_DATA, 2, LENGTH(A.OBJECT_DATA) - 2) AS ITEMID, B.ITEM_NM
FROM RULECONDITION_POSTFIXOBJECT_HI A INNER JOIN RULEITEM B ON SUBSTR(A.OBJECT_DATA, 2, LENGTH(A.OBJECT_DATA) - 2) = B.ITEMID
WHERE A.DATATYPE_CD = 3
AND RULEID = #{ruleid}
AND RULE_VERNO = #{ruleVerno}
UNION ALL
SELECT DISTINCT '반환값' AS USE_GUBUN, SUBSTR(A.OBJECT_DATA, 2, LENGTH(A.OBJECT_DATA) - 2) AS ITEMID, B.ITEM_NM
FROM RULECONDITIONRETURN_POSTOB_HI A INNER JOIN RULEITEM B ON SUBSTR(A.OBJECT_DATA, 2, LENGTH(A.OBJECT_DATA) - 2) = B.ITEMID
WHERE A.DATATYPE_CD = 3
AND RULEID = #{ruleid}
AND RULE_VERNO = #{ruleVerno}

SELECT DISTINCT '조건식' AS USE_GUBUN , SUBSTR(A.OBJECT_DATA, 3, LENGTH(A.OBJECT_DATA) - 3) AS RULEID , B.RULE_NM ,(select code_nm from clover_code where code_type='604' and code = B.RULE_STATE) as RULE_STATE ,(select user_nm from clover_user where user_id = B.UPDATE_USERID) as UPDATE_USERID ,(SUBSTR(B.UPDATE_DATETIME,0,4)||'/'||SUBSTR(B.UPDATE_DATETIME,5,2)||'/'||SUBSTR(B.UPDATE_DATETIME,7,2)||' '||SUBSTR(B.UPDATE_DATETIME,9,2)||':'||SUBSTR(B.UPDATE_DATETIME,11,2)||':'||SUBSTR(B.UPDATE_DATETIME,13,2) )as UPDATE_DATETIME , B.RULE_APPLY_YN FROM RULECONDITION_POSTFIXOBJECT_HI A INNER JOIN RULE B ON SUBSTR(A.OBJECT_DATA, 3, LENGTH(A.OBJECT_DATA) - 3) = B.RULEID WHERE A.DATATYPE_CD = 4 AND A.RULEID = #{ruleid} AND A.RULE_VERNO = #{ruleVerno}
UNION ALL
SELECT DISTINCT '반환값' AS USE_GUBUN , SUBSTR(A.OBJECT_DATA, 3, LENGTH(A.OBJECT_DATA) - 3) AS RULEID , B.RULE_NM ,(select code_nm from clover_code where code_type='604' and code = B.RULE_STATE) as RULE_STATE ,(select user_nm from clover_user where user_id = B.UPDATE_USERID) as UPDATE_USERID ,(SUBSTR(B.UPDATE_DATETIME,0,4)||'/'||SUBSTR(B.UPDATE_DATETIME,5,2)||'/'||SUBSTR(B.UPDATE_DATETIME,7,2)||' '||SUBSTR(B.UPDATE_DATETIME,9,2)||':'||SUBSTR(B.UPDATE_DATETIME,11,2)||':'||SUBSTR(B.UPDATE_DATETIME,13,2) )as UPDATE_DATETIME , B.RULE_APPLY_YN FROM RULECONDITIONRETURN_POSTOB_HI A INNER JOIN RULE B ON SUBSTR(A.OBJECT_DATA, 3, LENGTH(A.OBJECT_DATA) - 3) = B.RULEID WHERE A.DATATYPE_CD = 4 AND A.RULEID = #{ruleid} AND A.RULE_VERNO = #{ruleVerno}

SELECT COUNT(*)
  FROM RULE
  WHERE RULE_STATE != 'D'
  AND RULE_NM = #{ruleNm}

      AND RULEID != #{ruleid}

SELECT COUNT(*)
FROM RULE
WHERE RULE_STATE != 'D'
AND RULEALIAS_NM = #{rulealiasNm}

    AND RULEID != #{ruleid}
